        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Task to check expected value of q
    task check_q;
        input [3:0] expected;
        begin
            if (q !== expected) begin
                $display("ERROR at time %0t: expected q = %0d, got q = %0d", $time, expected, q);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;

        // Apply reset for 2 clock cycles
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        check_q(4'd1);

        // Keep reset high for another cycle to ensure it holds 1
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        check_q(4'd1);

        // Release reset and observe counting 2 through 10, then wrap to 1
        @(negedge clk);
        reset = 0;

        // Check full sequence across two complete cycles (20 counts)
        for (i = 0; i < 20; i = i + 1) begin
            @(posedge clk);
            #1;
            // The sequence after release should be:
            // i=0: 2, i=1: 3, ..., i=8: 10, i=9: 1, i=10: 2, ...
            check_q(((i + 1) % 10) + 1);
        end

        // Assert reset mid-count (when q is currently around some value)
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        check_q(4'd1);

        // Advance 4 counts: 2, 3, 4, 5
        @(negedge clk);
        reset = 0;
        @(posedge clk); #1; check_q(4'd2);
        @(posedge clk); #1; check_q(4'd3);
        @(posedge clk); #1; check_q(4'd4);
        @(posedge clk); #1; check_q(4'd5);

        // Reset again mid-sequence
        @(negedge clk);
        reset = 1;
        @(posedge clk); #1; check_q(4'd1);

        // Count up to 10
        @(negedge clk);
        reset = 0;
        for (i = 2; i <= 10; i = i + 1) begin
            @(posedge clk);
            #1;
            check_q(i[3:0]);
        end

        // Reset precisely at roll-over boundary (when count is 10)
        @(negedge clk);
        reset = 1;
        @(posedge clk); #1; check_q(4'd1);

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
